from fractions import Fraction as F
import json
rows=[('A',5,(0,0,0,1)),('A',6,(1,0,1,0)),('B',11,(0,0,0,1)),('B',5,(0,1,1,0)),('C',6,(0,1,0,1)),('C',4,(1,0,1,1)),('D',6,(0,0,1,0)),('D',8,(1,1,0,0))]
loss=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
tests='TUVW'; costs=[F(1),F(1),F(17,10),F(21,10)]
def mass(s): return sum(rows[i][1] for i in s)
def stop(s):
    return min((F(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in s),mass(s)),'ABCD'[a]) for a in range(4))
def value(s, available, remaining):
    choices=[stop(s)]
    if remaining:
        for t in available:
            v=costs[t]
            for b in (0,1):
                sub=tuple(i for i in s if rows[i][2][t]==b)
                if sub: v+=F(mass(sub),mass(s))*value(sub,tuple(x for x in available if x!=t),remaining-1)[0]
            choices.append((v,tests[t]))
    return min(choices)
s=tuple(range(8)); first_losses={'STOP':float(stop(s)[0])}
for t in range(4):
    first_losses[tests[t]]=float(costs[t]+sum(F(mass(sub),mass(s))*value(sub,tuple(x for x in range(4) if x!=t),1)[0] for b in (0,1) if (sub:=tuple(i for i in s if rows[i][2][t]==b))))
v,first=value(s,tuple(range(4)),2)
next_actions={}
if first in tests:
    t=tests.index(first)
    for b in (0,1):
        sub=tuple(i for i in s if rows[i][2][t]==b)
        next_actions[str(b)]=value(sub,tuple(x for x in range(4) if x!=t),1)[1] if sub else 'IMPOSSIBLE'
print(json.dumps({'first':first,'first_losses':first_losses,'next':next_actions}))
print('Optimal exact loss:',v,'total weight',mass(s))
for b in (0,1):
    sub=tuple(i for i in s if rows[i][2][tests.index(first)]==b)
    print('Branch',b,'weight',mass(sub),'stop',stop(sub),'optimal',value(sub,tuple(x for x in range(4) if tests[x]!=first),1))

