from fractions import Fraction as F
import json
# U=0 selects original rows once; repeated display is the identical event.
rows=[('A',5,(0,0,1)),('A',6,(1,1,0)),('B',11,(0,0,1)),('C',4,(1,1,1)),('D',6,(0,1,0))]
modes='ABCD'; tests='TVW'; costs={'T':F(7),'V':F(17,10),'W':F(21,10)}
L={'A':[0,7,10,21],'B':[7,0,22,11],'C':[19,13,0,19],'D':[12,6,13,0]}
def mass(rs): return sum(r[1] for r in rs)
def repair_losses(rs): return {a:F(sum(w*L[a][modes.index(m)] for m,w,_ in rs),mass(rs)) for a in modes}
def best(rs): return min((v,a) for a,v in repair_losses(rs).items())
posterior={m:float(F(sum(w for mode,w,_ in rows if mode==m),mass(rows))) for m in modes}
remaining=repair_losses(rows)
branches={}
for j,t in enumerate(tests):
    v=costs[t]; branches[t]={}
    for b in (0,1):
        rs=[r for r in rows if r[2][j]==b]
        if rs:
            loss,a=best(rs); v+=F(mass(rs),mass(rows))*loss; branches[t][str(b)]=a
        else: branches[t][str(b)]='IMPOSSIBLE'
    remaining[t]=v
action=min(remaining,key=remaining.get)
# Independently calculated mode totals and optimal weighted losses for each test.
assert posterior=={'A':11/32,'B':11/32,'C':4/32,'D':6/32}
assert remaining['T']==7+F(101+40,32)
assert remaining['V']==F(17,10)+F(35+124,32)
assert remaining['W']==F(21,10)+F(72+117,32)
print(json.dumps({'posterior':posterior,'remaining_losses':{k:float(v) for k,v in remaining.items()},'action':action,'repair_after':branches.get(action,{})}))

